// @vitest-environment jsdom
import { createElement } from 'react'
import { test, expect } from 'vitest'
import { render, fireEvent, waitFor, cleanup } from '@testing-library/react'
import { App } from './App'

test('Compact toggles button and panel classes', async () => {
  const screen = render(createElement(App))
  try {
    const button = screen.getByRole('button', { name: 'Compact' })
    const panel = screen.getByRole('main')
    expect(button.previousElementSibling?.textContent).toBe('Priority only')
    expect(button.classList.contains('is-active')).toBe(false)
    expect(panel.classList.contains('compact')).toBe(false)
    fireEvent.click(button)
    await waitFor(() => {
      expect(button.classList.contains('is-active')).toBe(true)
      expect(panel.classList.contains('compact')).toBe(true)
      expect(button.getAttribute('aria-pressed')).toBe('true')
    })
    fireEvent.click(button)
    await waitFor(() => {
      expect(button.classList.contains('is-active')).toBe(false)
      expect(panel.classList.contains('compact')).toBe(false)
      expect(button.getAttribute('aria-pressed')).toBe('false')
    })
  } finally {
    cleanup()
  }
})
EOF
